evere","Elge, urokser, vildsvin og bævere"]},{"objective":"reformation_monarchy","grade":6,"band":4,"before_hash":"83f31d935cd6571deb84a9db6344a754","after_hash":"a4644944805ce2f9e792f01361879aee","before_metadata_hash":"111fa59612208344a6fbfa4cb0390f73","after_metadata_hash":"111fa59612208344a6fbfa4cb0390f73","changes":[{"path":["content","options","1"],"before":"Han sagde at konger burde afsaette paven militaert","after":"Han sagde at konger burde afsætte paven militært"},{"path":["content","review_text"],"before":"Luthers revolutionaere idé var enkel men farlig: bibelen og den personlige samvittighed er over kirkens tradition og pavens autoritet. Det udfordrede ikke blot religionen men hele den magtstruktur der var bygget paa kirkens monopol paa Guds ord.","after":"Luthers revolutionære idé var enkel men farlig: bibelen og den personlige samvittighed er over kirkens tradition og pavens autoritet. Det udfordrede ikke blot religionen men hele den magtstruktur der var bygget på kirkens monopol på Guds ord."}],"aliases":null},{"objective":"reformation_monarchy","grade":7,"band":2,"before_hash":"75accf98d801ecd673ce625f26724e50","after_hash":"d67c8db7c1797b84614fbc4566666c85","before_metadata_hash":"5f396dd80eb1f3cf190f111cfde6f0da","after_metadata_hash":"fa6226b21b074b8ec7f31d2d3ffb9f09","changes":[{"path":["content","correct"],"before":"Fordi den religiose og politiske revolution i toppen ikke aendrede de okonomiske og juridiske betingelser for boendernes liv","after":"Fordi den religiose og politiske revolution i toppen ikke ændrede de økonomiske og juridiske betingelser for bøndernes liv"},{"path":["content","options","0"],"before":"Fordi den religiose og politiske revolution i toppen ikke aendrede de okonomiske og juridiske betingelser for boendernes liv","after":"Fordi den religiose og politiske revolution i toppen ikke ændrede de økonomiske og juridiske betingelser for bøndernes liv"},{"path":["content","options","1"],"before":"Fordi boender var mod Reformation