sen."}],"aliases":null},{"objective":"prehistoric_denmark","grade":4,"band":1,"before_hash":"32937be8722a655bb3af4bc870f8187b","after_hash":"7ddf5d8366b53f0b2df3a25680f08597","before_metadata_hash":"a3805168c29054c469a9594143cd5d8c","after_metadata_hash":"5d0b12b195e5a5f3f7f42ad2b7e8fb9a","changes":[{"path":["content","correct"],"before":"Aeldre Stenalder med jaeger-samlere og Yngre Stenalder med boender","after":"Ældre Stenalder med jæger-samlere og Yngre Stenalder med bønder"},{"path":["content","options","0"],"before":"Aeldre Stenalder med jaeger-samlere og Yngre Stenalder med boender","after":"Ældre Stenalder med jæger-samlere og Yngre Stenalder med bønder"},{"path":["content","options","1"],"before":"Tidlig Stenalder og Sen Stenalder begge med boender","after":"Tidlig Stenalder og Sen Stenalder begge med bønder"},{"path":["content","review_text"],"before":"Danmarks Stenalder deles i to. Aeldre Stenalder: folk jagede og samlede. Yngre Stenalder: folk begyndte at dyrke marker og holde husdyr. Det er to meget forskellige maader at leve paa.","after":"Danmarks Stenalder deles i to. Ældre Stenalder: folk jagede og samlede. Yngre Stenalder: folk begyndte at dyrke marker og holde husdyr. Det er to meget forskellige måder at leve på."},{"path":["content","accepted_answers","0"],"before":"Aeldre Stenalder med jaeger-samlere og Yngre Stenalder med boender","after":"Ældre Stenalder med jæger-samlere og Yngre Stenalder med bønder"}],"aliases":["Aeldre Stenalder med jaeger-samlere og Yngre Stenalder med boender","Ældre Stenalder med jæger-samlere og Yngre Stenalder med bønder"]},{"objective":"prehistoric_denmark","grade":4,"band":1,"before_hash":"22cab17a5853982ce13e779e50ffaa1d","after_hash":"f8a61f163e3b716e07bdc1fc60589900","before_metadata_hash":"5ef3492a058578f9cbc13d9ea0612674","after_metadata_hash":"26da7490f7798fcbd3c707bfafad8696","changes":[{"path":["content","correct"],"before":"Millioner af muslinge- og ostersskaller rester fra mange maaltider","after":"Millione