,"grade":8,"band":2,"before_hash":"381b1d236bfdade8e0a0b09cc8a1e25e","after_hash":"5049105e109667cf74cbe9e671ba7979","before_metadata_hash":"3f4a2c04a0a91ff8cb418197403fab52","after_metadata_hash":"3f4a2c04a0a91ff8cb418197403fab52","changes":[{"path":["content","options","3"],"before":"Propaganda naesten udelukkende via aviser","after":"Propaganda næsten udelukkende via aviser"},{"path":["content","review_text"],"before":"Goebbels vidste at simple gentagne budskaber virker bedre end komplekse argumenter. Joderne og kommunisterne var fjenderne. Radio, film og aviser var statslige. Nurnberg-rallies skabte en religioes stemning om Hitler. Propaganda var systematisk og altgennemtraengende.","after":"Goebbels vidste at simple gentagne budskaber virker bedre end komplekse argumenter. Joderne og kommunisterne var fjenderne. Radio, film og aviser var statslige. Nurnberg-rallies skabte en religiøs stemning om Hitler. Propaganda var systematisk og altgennemtrængende."}],"aliases":null},{"objective":"world_war_2","grade":7,"band":5,"before_hash":"10089e3d68d01eeda338872566d9d782","after_hash":"21555c40ff99ae716f1f92c1f6d48715","before_metadata_hash":"12508bb4885fda586e37a0aa89875496","after_metadata_hash":"c066419f0cd859e8955be442fd2ff21a","changes":[{"path":["content","correct"],"before":"Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det undersoetter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","after":"Eksperimentet viste at ordinære mennesker er villige til at påføre andre alvorlig skade når en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke krævede monstre men systemer der normaliserede lydighed"},{"path":["content","options","0"],"before":"Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det undersoetter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","after":"Eksperimentet viste at ordinære mennesker er villige til at påføre andre alvorlig skade når en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke krævede monstre men systemer der normaliserede lydighed"},{"path":["content","options","1"],"before":"Eksperimentet beviste at alle mennesker er naturligt onde og bevidst oensker at skade andre","after":"Eksperimentet beviste at alle mennesker er naturligt onde og bevidst ønsker at skade andre"},{"path":["content","question"],"before":"Hvad fortaeller Milgrams lydigheds-eksperiment (1961) om de psykologiske mekanismer bag Holocaust?","after":"Hvad fortæller Milgrams lydigheds-eksperiment (1961) om de psykologiske mekanismer bag Holocaust?"},{"path":["content","review_text"],"before":"Stanley Milgram udfoerte sit lydigheds-eksperiment i 1961. Forsogspersoner blev bedt om at give elektrisk stoed til en skuespiller i et andet rum. 65 procent gave de staerkeste stoed paa trods af hoere raab. Milgram fortolkede det som lydighed over for autoritet under et system der frigjorde individet fra ansvar. Hannah Arendt moenttede begrebet det ondes banalitet om Eichmann — en bureaukrat der organiserede Holocaust ikke af had men af embedslydig. Moralsk ondskab kraever ikke monstre — det kraever systemer der normaliserer ondskab.","after":"Stanley Milgram udførte sit lydigheds-eksperiment i 1961. Forsogspersoner blev bedt om at give elektrisk stød til en skuespiller i et andet rum. 65 procent gave de stærkeste stød på trods af høre råb. Milgram fortolkede det som lydighed over for autoritet under et system der frigjorde individet fra ansvar. Hannah Arendt møntede begrebet det ondes banalitet om Eichmann — en bureaukrat der organiserede Holocaust ikke af had men af embedslydig. Moralsk ondskab kræver ikke monstre — det kræver systemer der normaliserer ondskab."},{"path":["content","accepted_answers","0"],"before":"Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det undersoetter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","after":"Eksperimentet viste at ordinære mennesker er villige til at påføre andre alvorlig skade når en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke krævede monstre men systemer der normaliserede lydighed"}],"aliases":["Eksperimentet viste at ordinaere mennesker er villige til at paafore andre alvorlig skade naar en autoritetsfigur beordrer dem til det — det undersoetter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke kraevede monstre men systemer der normaliserede lydighed","Eksperimentet viste at ordinære mennesker er villige til at påføre andre alvorlig skade når en autoritetsfigur beordrer dem til det — det understøtter Hannah Arendts tese om det ondes banalitet og viser at Holocaust ikke krævede monstre men systemer der normaliserede lydighed"]},{"objective":"world_war_1","grade":7,"band":2,"before_hash":"7ceea641e3a63feb81b6240d3040b61b","after_hash":"0e1d7c4c38c115122de32c916a8f83ae","before_metadata_hash":"625a0e635de3149fae2ea422d953f647","after_metadata_hash":"73014239b41b18b4d41a72ac2322ed3f","changes":[{"path":["content","correct"],"before":"En konkurrence mellem de store magter om at opbygge storre og staerkere haer og flaader end sine rivaler","after":"En konkurrence mellem de store magter om at opbygge større og stærkere hær og flåder end sine rivaler"},{"path":["content","options","0"],"before":"En konkurrence mellem de store magter om at opbygge storre og staerkere haer og flaader end sine rivaler","after":"En konkurrence