ev tvunget til at kæmpe og dø i andres krig og fik ikke de friheder de var lovet som belønning bagefter"},{"path":["content","options","2"],"before":"Koloniserede folk kaeampede ikke i krigen","after":"Koloniserede folk kæmpede ikke i krigen"},{"path":["content","options","3"],"before":"Koloniserede folk fik fuld selvstaendighed straks efter krigen","after":"Koloniserede folk fik fuld selvstændighed straks efter krigen"},{"path":["content","question"],"before":"Hvad betod Forste Verdenskrig for de koloniserede folk i Afrika og Asien?","after":"Hvad betød Første Verdenskrig for de koloniserede folk i Afrika og Asien?"},{"path":["content","review_text"],"before":"Over en million soldater fra franske og britiske kolonier kaeampede i krigen. Mange var tvangsindrullerede. De fik loefter om politiske reformer. Men efter krigen geninfoerte kolonimagterne det gamle system. Det saaede froe til befrielsesbevaegelserne der folgete.","after":"Over en million soldater fra franske og britiske kolonier kæmpede i krigen. Mange var tvangsindrullerede. De fik løfter om politiske reformer. Men efter krigen genindførte kolonimagterne det gamle system. Det såede frø til befrielsesbevægelserne der fulgte."},{"path":["content","accepted_answers","0"],"before":"De blev tvunget til at kaempe og doe i andres krig og fik ikke de friheder de var lovet som beloening bagefter","after":"De blev tvunget til at kæmpe og dø i andres krig og fik ikke de friheder de var lovet som belønning bagefter"}],"aliases":["De blev tvunget til at kaempe og doe i andres krig og fik ikke de friheder de var lovet som beloening bagefter","De blev tvunget til at kæmpe og dø i andres krig og fik ikke de friheder de var lovet som belønning bagefter"]}]$patches$::jsonb;
  patch jsonb;
  change jsonb;
  target public.questions%ROWTYPE;
  new_content jsonb;
  new_metadata jsonb;
  path text[];
  current_fn_hash text;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  -- Kort skrivelås sikrer, at alle førværdier kontrolleres og ændres atomisk.
  LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
  SELECT md5(pg_get_functiondef('public.process_question_attempt(uuid,uuid,text,bigint)'::regprocedure))
  INTO current_fn_hash;
  IF current_fn_hash NOT IN ('ac2b7526545be60fecae54a95c75f6b8', '176699d16ca58c5f2d4846b617bbba70') THEN
    RAISE EXCEPTION 'Bedømmelsesfunktionen er ændret; kræver ny gennemgang';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.questions'::regclass AND NOT tgisinternal) THEN
    RAISE EXCEPTION 'Nye spørgsmålstriggere kræver gennemgang';
  END IF;

  FOR patch IN SELECT value FROM jsonb_array_elements(patches) LOOP
    SELECT * INTO STRICT target FROM public.questions
    WHERE learning_objective = patch->>'objective'
      AND target_grade IS NOT DISTINCT FROM (patch->>'grade')::smallint
      AND difficulty_band IS NOT DISTINCT FROM (patch->>'band')::integer
      AND md5(content::text) IN (patch->>'before_hash', patch->>'after_hash')
    FOR UPDATE;
    IF md5(target.content::text) = patch->>'after_hash'
       AND md5(coalesce(target.metadata,'null'::jsonb)::text) = patch->>'after_metadata_hash' THEN
      CONTINUE;
    END IF;
    IF md5(target.content::text) IS DISTINCT FROM patch->>'before_hash'
       OR md5(coalesce(target.metadata,'null'::jsonb)::text) IS DISTINCT FROM patch->>'before_metadata_hash' THEN
      RAISE EXCEPTION 'Opgavens førværdier er ændret; kræver ny gennemgang';
    END IF;
    new_content := target.content;
    new_metadata := target.metadata;

    FOR change IN SELECT value FROM jsonb_array_elements(patch->'changes') LOOP
      SELECT array_agg(value ORDER BY ordinality) INTO path
      FROM jsonb_array_elements_text(change->'path') WITH ORDINALITY;
      IF path[1] = 'content' THEN
        IF new_content #> path[2:] IS DISTINCT FROM change->'before' THEN
          RAISE EXCEPTION 'Indholdsfelt er ændret';
        END IF;
        new_content := jsonb_set(new_content, path[2:], change->'after', false);
      ELSIF path = ARRAY['metadata','review_text'] THEN
        IF new_metadata->'review_text' IS DISTINCT FROM change->'before' THEN
          RAISE EXCEPTION 'Forklaring er ændret';
        END IF;
        new_metadata := jsonb_set(new_metadata, '{review_text}', change->'after', false);
      ELSE
        RAISE EXCEPTION 'Ukendt tekstfelt';
      END IF;
    END LOOP;
    IF patch->'aliases' <> 'null'::jsonb THEN
      new_metadata := jsonb_set(coalesce(new_metadata, '{}'::jsonb), '{danish_orthography_correct_aliases}', patch->'aliases', true);
    END IF;
    IF md5(new_content::text) IS DISTINCT FROM patch->>'after_hash'
       OR md5(coalesce(new_metadata,'null'::jsonb)::text) IS DISTINCT FROM patch->>'after_metadata_hash' THEN
      RAISE EXCEPTION 'Uventet resultat af tekstrettelse';
    END IF;
    UPDATE public.questions SET content = new_content, metadata = new_metadata WHERE id = target.id;
  END LOOP;
  -- CREATE OR REPLACE bevarer eksisterende ejer og EXECUTE-rettigheder.
  EXECUTE $grading$
CREATE OR REPLACE FUNCTION public.process_question_attempt(p_student_id uuid, p_question_instance_id uuid, p_answer text, p_question_shown_at bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_instance       record;
  v_correct        boolean := false;
  v_answer         text;
  v_correct_answer text;
  v_rows_updated   integer;
  v_is_repeat      boolean := false;
  v_xp             integer := 0;
  v_coins          integer := 0;
  v_orthography_aliases jsonb;
BEGIN

  SELECT qi.*, q.answer_format, q.content AS question_content, q.metadata AS question_metadata
  INTO v_instance
  FROM question_instances qi
  JOIN questions q ON q.id = qi.question_id
  WHERE qi.id         = p_question_instance_id
    AND qi.student_id = p_student_id;

  IF v_instance IS NULL THEN
    RAISE EXCEPTION 'Instance not found';
  END IF;

  -- Only the reviewed old/new spellings of this question's correct option are aliases.
  -- The stored answer key and all historical pupil answers/results remain unchanged.
  v_orthography_aliases := v_instance.question_metadata->'danish_orthography_correct_aliases';
  IF jsonb_typeof(v_orthography_aliases) IS DISTINCT FROM 'array' THEN
    v_orthography_aliases := '[]'::jsonb;
  END IF;
  IF jsonb_array_length(v_orthography_aliases) = 2
     AND v_orthography_aliases ? v_instance.correct_answer
     AND v_orthography_aliases ? (v_instance.question_content->>'correct') THEN
    v_instance.correct_answer := v_instance.question_content->>'correct';
  ELSE
    v_orthography_aliases := '[]'::jsonb;
  END IF;

  IF v_instance.answered = true THEN
    RETURN json_build_object(
      'status', CASE
        WHEN v_instance.was_correct = true  THEN 'correct'
        WHEN v_instance.was_correct = false THEN 'incorrect'
        ELSE 'pending'
      END,
      'correct_answer', v_instance.correct_answer
    );
  END IF;

  v_is_repeat := coalesce(v_instance.repeat_count, 0) > 0;

  IF v_instance.answer_format = 'text' THEN
    UPDATE question_instances
    SET answered = true, answered_at = now(), user_answer = p_answer, was_correct = null
    WHERE id = v_instance.id AND answered = false;

    RETURN json_build_object('status', 'pending', 'correct_answer', null);
  END IF;

  v_answer         := trim(regexp_replace(lower(p_answer),                   '[^a-z0-9]', '', 'g'));
  v_correct_answer := trim(regexp_replace(lower(v_instance.correct_answer), '[^a-z0-9]', '', 'g'));

  IF v_answer = v_correct_answer OR v_orthography_aliases ? p_answer THEN
    v_correct := true;
  END IF;

  UPDATE question_instances
  SET
    answered    = true,
    answered_at = now(),
    user_answer = p_answer,
    was_correct = v_correct
  WHERE id       = v_instance.id
    AND answered = false;

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

  -- A concurrent call already scored this instance: award nothing, report the same result.
  IF v_rows_updated = 0 THEN
    RETURN json_build_object(
      'status',         CASE WHEN v_correct THEN 'correct' ELSE 'incorrect' END,
      'correct_answer', v_instance.correct_answer
    );
  END IF;

  IF v_correct THEN
    IF v_is_repeat THEN
      -- A repeat earns a token amount of XP and nothing else. correct_answers and
      -- total_correct_answers stay put: they feed the accuracy figure teachers read, and
      -- re-answers of already known material would inflate it.
      v_xp := 2;
      UPDATE student_progress
      SET xp = COALESCE(xp, 0) + v_xp
      WHERE student_id = p_student_id;
    ELSE
      v_xp    := 10;
      v_coins := 5;
      UPDATE student_progress
      SET
        xp                    = COALESCE(xp, 0) + v_xp,
        coins                 = COALESCE(coins, 0) + v_coins,
        correct_answers       = COALESCE(correct_answers, 0) + 1,
        total_correct_answers = COALESCE(total_correct_answers, 0) + 1
      WHERE student_id = p_student_id;
    END IF;
  END IF;

  -- A streak measures showing up, which a pupil practising repeats has genuinely done.
  PERFORM public.update_streak(p_student_id);

  -- Quest progress is NOT advanced by repeats: quest rewards are coins, and the pool-exhausted
  -- pupil could otherwise complete quests indefinitely on questions they already know.
  IF NOT v_is_repeat THEN
    PERFORM public.update_quest_progress_for_answer(
      p_student_id,
      v_correct,
      CASE WHEN v_correct THEN 10 ELSE 0 END
    );
    PERFORM public.update_weekly_quest_progress_for_answer(
      p_student_id,
      v_correct,
      CASE WHEN v_correct THEN 10 ELSE 0 END
    );
  END IF;

  RETURN json_build_object(
    'status',         CASE WHEN v_correct THEN 'correct' ELSE 'incorrect' END,
    'correct_answer', v_instance.correct_answer
  );

END;
$function$
  $grading$;
END
$danish_text$;
